'use strict';
// A classroom writing aid, not plagiarism detection or a security boundary.
const integrity={accepted:false,ownClipboard:null};
const normalizeQuote=value=>value.replace(/\s+/gu,' ').trim();
function sourceQuote(value){
 const text=normalizeQuote(value).replace(/^[«“"]|[»”"]$/gu,'').trim();
 if([...text].length<8||[...text].length>220)return null;
 const index=BOOK.paragraphs.findIndex(p=>normalizeQuote(p).includes(text));
 if(index<0)return null;
 const split=BOOK.paragraphs.findIndex(p=>p.trim()==='2-бөлім');
 return {text,part:index<split?1:2};
}
function integrityRules(){return `<ol><li><b>Талдауды өзің жаз.</b> Сыныптасыңның, сайттың немесе жасанды интеллектінің дайын жауабын өз еңбегің ретінде ұсынба.</li><li><b>Дәйексөзді белгіле.</b> Автор сөзін «тырнақшаға» алып, Б. Момышұлы, «Ұшқан ұя» және бөлімін көрсет. Дәйексөзден кейін өз түсіндіруің болсын.</li><li><b>Өзгенің ойының дереккөзін көрсет.</b> Өз сөзіңмен жеткізсең де, пайдаланған дереккөзді ата. ЖИ мен өзге көмекті мұғалім рұқсат еткен шекте ғана қолдан және қолданғаныңды ашық жаз.</li><li><b>Кері байланысты қолдан.</b> Үлгіні түсіну үшін оқы, жауабыңа дайын күйінде алма. Түзеткен ойыңды өз сөзіңмен түсіндіре ал.</li></ol>`;}
function integrityPage(){return head('АКАДЕМИЯЛЫҚ АДАЛДЫҚ','Өз ойың.<br><em>Өз дәлелің.</em>','Түпнұсқа мәтін — дәлел көзі. Талдау — сенің еңбегің.')+`<section class="card"><h2>Адал жұмыс ережелері</h2>${integrityRules()}</section><div class="grid2"><section class="card"><h3>Адал дәйексөз</h3><p>«Шырағы болсын, құлыным» (Б. Момышұлы, «Ұшқан ұя», 1-бөлім).</p><p>Осыдан кейін метафораның мағынасын, автор мақсатын және оқырманға әсерін өзің түсіндір.</p></section><section class="card"><h3>Дайын жауапты иемдену</h3><p>Басқа автордың талдауын көшіріп, бірнеше сөзін ауыстыру оны өз еңбегің етпейді. Авторын көрсетіп, өз пайымың мен дәлеліңді бөлек жаз.</p></section></div><section class="card"><h2>Жазу өрістеріндегі шектеулер</h2><p>Дайын сыртқы жауапты қою және мәтінді сүйреп енгізу шектелген. Бұл бетте өзің жазған жауап бөлігін қиып не көшіріп қайта қоюға болады.</p><p>Шығармадан 8–220 таңбалық дәл үзіндіні қоюға болады: платформа оны тырнақшамен және дереккөзбен енгізеді. Талдауыңды өзің жаз. Ұзын дәйексөзді қажет болса қолмен теріп, дереккөзін көрсет.</p><p>Талдау үлгілерін стандартты көшіру және сүйреу әрекеттері шектелген. Мәтінді оқу, таңдау және пернетақтамен басқару қолжетімді.</p></section><p class="notice">Бұл шектеулер көшіруді толық тоқтатпайды: скриншотты, қайта теруді немесе сыртқы көмекті анықтамайды. Плагиат не ЖИ детекторы қолданылмайды. Адалдық туралы растау — оқушының мәлімдемесі; жұмыс мұғалімнің талқылауы мен бағалауын қажет етеді.</p><a class="button" href="#final">Өз талдауыма өту →</a>`;}
function integrityPanel(){return `<section class="card integrity-panel" id="integrity-panel"><h2>Академиялық адалдық</h2><p>Жұмысты жүктемес бұрын дереккөздерді көрсетіп, өз еңбегің екенін раста. Мәтінді өзгертсең, растауды жаңарт.</p><details><summary>Адал жұмыс ережелерін оқу</summary>${integrityRules()}</details><label for="integrity-sources">Қосымша дереккөздер мен қолданылған көмек</label><textarea id="integrity-sources" data-draft="integrity-sources" rows="3" placeholder="Дереккөз атауы немесе сілтемесі және оны қалай пайдаландың. Қосымша көмек болмаса, солай көрсет.">${esc(state.drafts['integrity-sources']||'')}</textarea><p class="hint">Бұл өріске дереккөз сілтемесін қоюға болады. Ол талдау мәтініне автоматты түрде енгізілмейді.</p><div class="checklist"><label><input id="integrity-pledge" type="checkbox" ${integrity.accepted?'checked':''}><span>Талдауды өзім жаздым. Алынған сөздер мен ойлардың дереккөздерін және пайдаланған көмекті ашық көрсеттім. Жұмысымды өз сөзіммен түсіндіре аламын.</span></label></div><div id="integrity-status" class="hint" role="status">${integrity.accepted?'Осы нұсқа үшін растау берілді.':'Растау әлі берілмеді.'}</div><a class="text-link" href="#integrity">Толық ережелер және шектеулер →</a></section>`;}
function integrityEnhance(view){
 const isWriting=['read','lessons','workshop','final'].includes(view)&&!!document.querySelector('textarea[data-draft]');
 if(isWriting){const note=document.createElement('p');note.className='callout integrity-note';note.id='integrity-writing-note';note.innerHTML='<b>Өз ойыңды жаз.</b> Дайын сыртқы жауапты қою және сүйреп енгізу шектелген. Шығармадан қысқа дәл дәйексөзді дереккөзімен қоюға болады. <a href="#integrity">Ережелер</a>';const first=document.querySelector('textarea[data-draft]');first.previousElementSibling.insertAdjacentElement('beforebegin',note);for(const el of document.querySelectorAll('textarea[data-draft]'))if(el.dataset.draft!=='integrity-sources')el.setAttribute('aria-describedby','integrity-writing-note');}
 if(view==='final')document.querySelector('#final').previousElementSibling.insertAdjacentHTML('beforebegin',integrityPanel());
 if(view==='criteria')document.querySelector('#view').insertAdjacentHTML('afterbegin','<p class="callout"><a class="text-link" href="#integrity">Академиялық адалдық ережелері →</a> Дереккөзді көрсетіп, талдауды өз сөзіңмен жаз.</p>');
 if(view==='lessons')for(const el of document.querySelectorAll('.answer-model'))el.closest('details').dataset.modelAnswer='true';
 if(view==='workshop')for(const el of document.querySelectorAll('#view details'))el.dataset.modelAnswer='true';
}
function integrityNotice(target,message){
 let el=document.getElementById('integrity-feedback');if(!el){el=document.createElement('div');el.id='integrity-feedback';el.className='feedback error';el.setAttribute('role','status');el.setAttribute('aria-live','polite');}
 (target?.closest?.('details')||target||document.querySelector('#view')).insertAdjacentElement('afterend',el);el.textContent=message;
}
function writingTarget(target){return target instanceof HTMLTextAreaElement&&target.matches('[data-draft]')&&target.dataset.draft!=='integrity-sources';}
function insertWriting(target,value){target.setRangeText(value,target.selectionStart,target.selectionEnd,'end');target.dispatchEvent(new Event('input',{bubbles:true}));}
function modelSelection(){const selection=getSelection();if(!selection?.rangeCount||selection.isCollapsed)return null;const range=selection.getRangeAt(0);return [...document.querySelectorAll('[data-model-answer]')].find(el=>range.intersectsNode(el));}
for(const type of ['copy','cut'])document.addEventListener(type,event=>{
 const target=document.activeElement;
 if(writingTarget(target)){integrity.ownClipboard=target.value.slice(target.selectionStart,target.selectionEnd)||null;return;}
 integrity.ownClipboard=null;const model=modelSelection();if(model){event.preventDefault();integrityNotice(model,'Үлгіні дайын жауап ретінде көшіру шектелген. Ойды түсініп, талдауды өз сөзіңмен жаз.');}
});
document.addEventListener('paste',event=>{
 const target=event.target;if(!writingTarget(target))return;event.preventDefault();const text=event.clipboardData?.getData('text/plain')||'';
 if(text&&text===integrity.ownClipboard){insertWriting(target,text);integrityNotice(target,'Осы бетте өзің жазған мәтін бөлігі енгізілді. Ой сабақтастығын тексер.');return;}
 const quote=sourceQuote(text);if(quote){insertWriting(target,`«${quote.text}» (Б. Момышұлы, «Ұшқан ұя», ${quote.part}-бөлім). `);integrityNotice(target,'Мәтіннен қысқа дәйексөз дереккөзімен енгізілді. Оның мағынасы мен әсерін өз сөзіңмен түсіндір.');return;}
 integrityNotice(target,'Дайын сыртқы мәтінді қою шектелген. Талдауды өзің тер. Дәйексөз үшін шығармадан 8–220 таңбалық дәл үзіндіні таңда. Бұл әрекетке баға қойылмайды.');
});
document.addEventListener('beforeinput',event=>{if(writingTarget(event.target)&&['insertFromPaste','insertFromPasteAsQuotation','insertFromDrop'].includes(event.inputType)){event.preventDefault();integrityNotice(event.target,'Сыртқы мәтінді енгізу шектелген. Өз талдауыңды тер немесе шығармадан қысқа дәл дәйексөзді қой.');}});
document.addEventListener('dragover',event=>{if(writingTarget(event.target))event.preventDefault();});
document.addEventListener('drop',event=>{if(writingTarget(event.target)){event.preventDefault();integrityNotice(event.target,'Мәтінді сүйреп енгізу шектелген. Талдауды өзің жаз.');}});
document.addEventListener('dragstart',event=>{const model=event.target.closest?.('[data-model-answer]')||modelSelection();if(model){event.preventDefault();integrityNotice(model,'Талдау үлгісін сүйреп көшіру шектелген. Өз түсіндіруіңді жаз.');}});
document.addEventListener('input',event=>{if(event.target.matches?.('[data-draft]')){integrity.accepted=false;const check=document.getElementById('integrity-pledge');if(check)check.checked=false;const status=document.getElementById('integrity-status');if(status)status.textContent='Мәтін өзгерді. Соңғы нұсқаны қарап, растауды жаңарт.';}});
document.addEventListener('change',event=>{if(event.target.id==='integrity-pledge'){integrity.accepted=event.target.checked;state.saved=false;document.getElementById('integrity-status').textContent=integrity.accepted?'Осы нұсқа үшін растау берілді.':'Растау әлі берілмеді.';}});
function integrityExportReady(){if(!(state.drafts.final||'').trim()||integrity.accepted)return true;history.replaceState(null,'','#final');render();document.getElementById('integrity-panel').scrollIntoView({block:'center'});document.getElementById('integrity-status').textContent='Жүктеу үшін жұмысыңды тексеріп, өз еңбегің екенін раста. Бұл авторлықты автоматты тексеру емес.';document.getElementById('integrity-pledge').focus({preventScroll:true});return false;}
function integrityExportNote(){return '\n\nАКАДЕМИЯЛЫҚ АДАЛДЫҚ\n'+(integrity.accepted?'Оқушы осы нұсқаны өз еңбегі деп растады; алынған ойлар мен көмекті көрсеткенін мәлімдеді.':'Өз еңбегі туралы растау берілмеген.')+'\nБұл — оқушының мәлімдемесі, авторлықты не плагиаттың жоқтығын автоматты растау емес.\nҚосымша дереккөздер мен көмек: '+(state.drafts['integrity-sources']?.trim()||'Көрсетілмеген.');}
